import { Component, ElementRef, ViewChild, inject, signal, computed, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterLink, RouterLinkActive } from '@angular/router';
import { Api, Theme } from './api';
import { Chart } from './chart';
import { LiveReader } from './live-reader';
import { ItemVisual, ItemCatalog, PlayerHead, PlayerModel, registryId, visualIds } from './visuals';

const labels: Record<string, string> = {
  overview: 'Visão geral', players: 'Jogadores', worlds: 'Mundos', events: 'Atividade', explorer: 'Consultas', controls: 'Controles', audit: 'Auditoria', settings: 'Configuração', journey: 'Minha jornada', inventory: 'Meu inventário', statistics: 'Minhas estatísticas', advancements: 'Minhas conquistas', privacy: 'Privacidade',
  'server.snapshot': 'Informações do servidor', 'server.performance': 'Desempenho atual', 'worlds.list': 'Listar mundos', 'world.snapshot': 'Detalhes do mundo', 'chunk.snapshot': 'Chunk carregado', 'block.snapshot': 'Bloco e bioma', 'entity.snapshot': 'Consultar entidade', 'player.snapshot': 'Perfil do jogador', 'player.inventory': 'Inventário e Ender Chest', 'player.statistics': 'Estatísticas do jogador', 'player.advancements': 'Conquistas do jogador', 'statistics.catalog': 'Catálogo de estatísticas', 'host.filesystem': 'Armazenamento do servidor', 'integrations.status': 'Status das integrações', 'integration.luckperms': 'Grupo LuckPerms', 'integration.vault': 'Saldo Vault', 'integration.placeholder': 'Placeholder permitido', 'server.bans': 'Lista de banidos', 'server.operators': 'Operadores', 'server.whitelist': 'Whitelist',
  'player.kick': 'Expulsar jogador', 'player.ban': 'Banir jogador', 'player.unban': 'Remover banimento', 'player.whitelist.add': 'Adicionar à whitelist', 'player.whitelist.remove': 'Remover da whitelist', 'player.message': 'Enviar mensagem privada', 'server.broadcast': 'Enviar aviso ao servidor', 'player.gamemode': 'Alterar modo de jogo', 'player.health': 'Ajustar vida', 'player.food': 'Ajustar fome', 'player.level': 'Ajustar nível', 'player.teleport': 'Teleportar com segurança', 'player.inventory.clear': 'Limpar inventário', 'world.time': 'Ajustar horário', 'world.weather': 'Alterar clima', 'world.difficulty': 'Alterar dificuldade', 'world.gamerule': 'Alterar regra do mundo', 'world.border': 'Ajustar borda', 'world.save': 'Salvar mundo', 'server.console': 'Executar comando permitido',
};
const queryFields: Record<string, string[]> = {
  'world.snapshot': ['worldId'], 'chunk.snapshot': ['worldId','x','z'], 'block.snapshot': ['worldId','x','y','z'], 'entity.snapshot': ['entityId'],
  'player.snapshot': ['playerId'], 'player.inventory': ['playerId'], 'player.statistics': ['playerId','statistic','material','entityType','offset'], 'player.advancements': ['playerId','offset'],
  'integration.luckperms': ['playerId'], 'integration.vault': ['playerId'], 'integration.placeholder': ['playerId','placeholder'], 'server.bans': ['offset'], 'server.operators': ['offset'], 'server.whitelist': ['offset'],
};
const fieldLabels: Record<string, string> = { playerId: 'UUID do jogador', worldId: 'UUID do mundo', entityId: 'UUID da entidade', reason: 'Motivo', message: 'Mensagem', mode: 'Modo de jogo', value: 'Valor', rule: 'Regra (minecraft:...)', size: 'Tamanho em blocos', command: 'Comando permitido', offset: 'Página: posição inicial', statistic: 'Estatística (opcional)', material: 'Material (se necessário)', entityType: 'Tipo de entidade (se necessário)', placeholder: 'Placeholder autorizado', x: 'Coordenada X', y: 'Coordenada Y', z: 'Coordenada Z' };

@Component({ selector: 'vos-panel', imports: [CommonModule, FormsModule, RouterLink, RouterLinkActive, Chart, ItemVisual, PlayerHead, PlayerModel], template: `
<div class="workspace" [class.nav-open]="navOpen()"><button class="nav-backdrop" (click)="navOpen.set(false)" aria-label="Fechar navegação"></button>
<aside class="sidebar"><a class="brand" [routerLink]="prefix() + '/overview'"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><span>Vanilla<span class="brand-sub">OnlineStats</span></span></a>
<span class="side-caption">{{isPlayer() ? 'MINHA ÁREA' : 'CENTRAL DO SERVIDOR'}}</span>
<nav aria-label="Menu principal">@for(item of navigation(); track item.id) {<a [routerLink]="prefix() + '/' + item.id" routerLinkActive="active" (click)="navOpen.set(false)"><span class="nav-symbol">{{item.icon}}</span>{{name(item.id)}}@if(item.id === 'events' && activeAlerts().length){<span class="nav-count">{{activeAlerts().length}}</span>}</a>}</nav>
<div class="side-bottom"><div class="side-help"><span>◈</span><strong>Um mundo de possibilidades.</strong><p>Seus dados. Sua comunidade.<br>Sua infraestrutura.</p></div>
<div class="theme-switch" aria-label="Aparência">@for(item of themes; track item.id){<button [class.selected]="theme.choice() === item.id" (click)="theme.set(item.id)" [attr.aria-label]="item.label" [attr.title]="item.label">{{item.icon}}</button>}</div>
<a class="source-link" href="https://github.com/rromeradev/VanillaOnlineStats" target="_blank" rel="noopener">Código-fonte ↗ <span>v0.5.1</span></a></div></aside>
<div class="workspace-main"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" (click)="navOpen.set(!navOpen())" aria-label="Abrir navegação">☰</button><span>{{isPlayer() ? 'Área Player' : 'Administração'}}</span><span class="crumb-slash">/</span><strong>{{name(section())}}</strong></div>
<div class="topbar-actions"><span class="refresh-status"><i class="live-dot" [class.offline]="!selected()?.online"></i>{{selected()?.online ? 'Servidor online' : 'Sem sinal recente'}}</span><button class="avatar-button" (click)="open('account')" [attr.aria-label]="'Conta de ' + api.identity()?.displayName">@if(isPlayer()){<vos-head [skin]="self()?.skin" [name]="api.identity()?.displayName || ''"/>}@else{ {{initials()}} }</button></div></header>
<main id="main-content"><div class="page-heading"><div><div class="eyebrow">{{isPlayer() ? 'SUA JORNADA SURVIVAL' : 'OBSERVABILIDADE & COMUNIDADE'}}</div><h1>{{headline()}}</h1><p>{{subtitle()}}</p></div><div class="heading-actions">@if(!isPlayer() && selected()){<select aria-label="Servidor selecionado" [ngModel]="serverId()" (ngModelChange)="selectServer($event)">@for(server of servers(); track server.id){<option [value]="server.id">{{server.name}}</option>}</select>}<span class="pill" role="status">{{streamState()}} · atualização automática</span></div></div>
@if(api.info().demo){<div class="notice demo-banner">AMBIENTE DE DEMONSTRAÇÃO · Os dados deste ambiente são simulados e não representam seu servidor.</div>}
@if(error()){<div class="error-banner" role="alert">{{error()}}</div>}@if(queryError()){<div class="notice" role="status">{{queryError()}} Nova tentativa automática.</div>}@if(notice()){<div class="success-banner" role="status">{{notice()}}</div>}
@if(loading() && !overview() && !self()){<div class="skeleton-grid"><div></div><div></div><div></div><div></div></div>}
@if(!selected() && !loading()){<section class="card empty large-empty"><div class="empty-icon">◈</div><h2>Seu próximo mundo começa aqui</h2><p>Vincule um servidor para começar a acompanhar dados reais do Paper.</p>@if(!isPlayer()){<button class="button primary" (click)="open('server')">+ Vincular servidor</button>}</section>}
@if(selected()) {
@if(!isPlayer()){<div class="server-strip"><div class="server-monogram">V</div><div><strong>{{selected().name}}</strong><span>{{metadata().paperVersion || heartbeat().paperVersion || 'Aguardando versão do Paper'}} · AuthMe {{heartbeat().authMeVersion || '—'}}</span></div><span class="pill" [class.ok]="selected().online">{{selected().online ? 'Online' : 'Sem telemetria recente'}}</span><span class="strip-last">Último sinal {{ago(selected().lastSeen)}}</span></div>}
@switch(section()) {
@case('overview') {
@if(isPlayer()){<section class="player-hero card"><div class="player-avatar"><vos-head [skin]="self()?.skin" [name]="api.identity()?.displayName || ''"/></div><div><span class="eyebrow">BEM-VINDO DE VOLTA</span><h2>{{api.identity()?.displayName}}</h2><p>{{self()?.profile ? 'Seu último estado observado está disponível abaixo.' : 'Aguardando sua primeira amostra autenticada.'}}</p></div><span class="pill">Área Player</span></section>
<div class="metric-grid"><div class="metric-card"><span>Nível</span><strong>{{self()?.profile?.payload?.level ?? '—'}}</strong><small>Último estado coletado</small></div><div class="metric-card"><span>Vida</span><strong>{{self()?.profile?.payload?.health ?? '—'}}<em> ♥</em></strong><small>Último estado coletado</small></div><div class="metric-card"><span>Fome</span><strong>{{self()?.profile?.payload?.food ?? '—'}}<em> / 20</em></strong><small>Último estado coletado</small></div><div class="metric-card"><span>Modo de jogo</span><strong class="text-metric">{{self()?.profile?.payload?.gamemode || '—'}}</strong><small>{{ago(self()?.profile?.occurredAt)}}</small></div></div>
<section class="card player-appearance"><vos-skin [skin]="self()?.skin" [name]="api.identity()?.displayName || ''"/><div><h2>Sua aparência no servidor</h2><p class="muted">Skin efetiva observada, incluindo personalizações do SkinsRestorer.</p></div></section><section class="card"><div class="card-heading"><div><h2>Sua atividade recente</h2><p>Apenas os eventos vinculados à sua identidade.</p></div><a [routerLink]="prefix() + '/journey'" class="text-link">Ver jornada →</a></div>@if(self()?.events?.length){<div class="activity-list">@for(event of recentSelf(); track event.id){<div class="activity-row"><span class="event-assets">@if(event.payload?.uuid || isPlayer()){<vos-head [skin]="eventSkin(event)" [name]="event.payload?.name || api.identity()?.displayName || ''"/>}@else{<span class="event-icon">◈</span>}</span><div><strong>{{eventName(event.type)}}</strong><small>{{date(event.occurredAt)}}</small></div><span>{{ago(event.occurredAt)}}</span></div>}</div>}@else{<div class="empty"><span class="empty-icon">◷</span><strong>Sua história está começando</strong><p>Eventos aparecem após a coleta ser habilitada e sua conta se autenticar no jogo.</p></div>}</section>
} @else {
<div class="metric-grid"><div class="metric-card"><div><span>TPS do servidor</span><span class="metric-symbol">⌁</span></div><strong>{{number(perf().tps?.[0], 2)}}<em> / 20</em></strong><small><i class="live-dot" [class.offline]="!selected().online"></i>{{perf().tps ? perf().tps[0] >= 18 ? 'Dentro do esperado' : 'Abaixo do limiar de 18 TPS' : 'Aguardando telemetria'}}</small></div>
<div class="metric-card"><div><span>Tempo por tick</span><span class="metric-symbol">◷</span></div><strong>{{number(perf().msptAverage, 1)}}<em> ms</em></strong><small>P95 {{number(perf().msptP95, 1)}} ms · janela do Paper</small></div>
<div class="metric-card"><div><span>Jogadores online</span><span class="metric-symbol">♧</span></div><strong>{{perf().playersOnline ?? heartbeat().playersOnline ?? '—'}}<em>@if(metadata().maxPlayers){ / {{metadata().maxPlayers}}}</em></strong><small>Conexões atuais no Paper</small></div>
<div class="metric-card"><div><span>Memória da JVM</span><span class="metric-symbol">▤</span></div><strong>{{perf().heapUsed != null ? number(perf().heapUsed / 1073741824, 2) : '—'}}<em> GB</em></strong><div class="meter"><span [style.width.%]="heapPercent()"></span></div><small>{{perf().heapMax > 0 ? number(heapPercent(), 0) + '% do heap máximo' : 'Aguardando telemetria'}}</small></div></div>
<div class="overview-grid"><section class="card performance-card"><div class="card-heading"><div><h2>O ritmo do seu servidor</h2><p>Histórico real de desempenho</p></div><div class="segmented compact">@for(hour of hoursOptions; track hour){<button [class.selected]="hours() === hour" (click)="changeHours(hour)">{{hour === 168 ? '7 dias' : hour + 'h'}}</button>}</div></div><div class="chart-toolbar"><div class="chart-tabs"><button [class.active]="metric() === 'tps'" (click)="metric.set('tps')">TPS</button><button [class.active]="metric() === 'mspt'" (click)="metric.set('mspt')">MSPT</button><button [class.active]="metric() === 'heap'" (click)="metric.set('heap')">Memória</button></div><span class="small muted">{{metrics().length}} amostras</span></div><vos-chart [data]="metrics()" [metric]="metric()" [label]="'Histórico de ' + metric()"/></section>
<section class="card alerts-card"><div class="card-heading"><div><h2>Na sua atenção</h2><p>Limiares da última amostra</p></div><span class="counter">{{activeAlerts().length}}</span></div>@if(activeAlerts().length){@for(alert of activeAlerts(); track alert.rule){<div class="alert-item"><div class="alert-mark">!</div><div><strong>{{alertName(alert.rule)}}</strong><p>{{number(alert.value, 1)}} {{alert.rule === 'low-tps' ? 'TPS' : alert.rule === 'high-mspt' ? 'ms' : '%'}}</p><small>{{date(alert.last_seen)}}</small></div><button class="icon-button" (click)="ack(alert.rule)" [disabled]="alert.acknowledged_by" [attr.aria-label]="'Reconhecer alerta ' + alertName(alert.rule)">{{alert.acknowledged_by ? '✓' : '↗'}}</button></div>}}@else{<div class="empty"><span class="calm-icon">✓</span><strong>{{perf().tps ? 'Tudo no seu ritmo' : 'Aguardando observações'}}</strong><p>{{perf().tps ? 'Nenhum limiar de alerta ultrapassado na última amostra recebida.' : 'Alertas serão calculados a partir da telemetria recebida.'}}</p></div>}<div class="connection-note"><i class="live-dot" [class.offline]="!selected().controlConnected"></i>Controle {{selected().controlConnected ? 'conectado' : 'desconectado'}}<span>Atualização ao vivo</span></div></section></div>
<section class="card"><div class="card-heading"><div><h2>Aconteceu no seu mundo</h2><p>Últimos eventos observados pelo plugin</p></div><a [routerLink]="prefix() + '/events'" class="text-link">Ver atividade →</a></div>@if(recentEvents().length){<div class="activity-list">@for(event of recentEvents(); track event.id){<div class="activity-row"><span class="event-assets">@if(event.payload?.uuid || isPlayer()){<vos-head [skin]="eventSkin(event)" [name]="event.payload?.name || api.identity()?.displayName || ''"/>}@else{<span class="event-icon">◈</span>}</span><div><strong>{{eventName(event.type)}}</strong><small>{{event.payload.name || event.payload.worldId || 'Servidor'}}</small></div><span>{{ago(event.occurredAt)}}</span></div>}</div>}@else{<div class="empty"><span class="empty-icon">◷</span><strong>Nenhum evento nesta janela</strong><p>As observações vão aparecer aqui conforme forem recebidas.</p></div>}</section>
}}
@case('players') {<section class="card"><div class="card-heading"><div><h2>Quem constrói essa história</h2><p>{{players().length}} perfis observados · a coleta de jogadores precisa estar habilitada</p></div><input class="search-input" [(ngModel)]="search" placeholder="Buscar por nome ou UUID" aria-label="Buscar jogador"></div>@if(filteredPlayers().length){<div class="table-scroll"><table><thead><tr><th>Jogador</th><th>Modo de jogo</th><th>Nível</th><th>Ping</th><th>Última amostra</th><th></th></tr></thead><tbody>@for(player of filteredPlayers(); track player.id){<tr><td><div class="table-person"><vos-head [skin]="player.payload.skin" [name]="player.payload.name || '?'"/><div><strong>{{player.payload.name}}</strong><small>{{short(player.id)}}</small></div></div></td><td><span class="pill">{{player.payload.gamemode}}</span></td><td>{{player.payload.level}}</td><td>{{player.payload.ping}} ms</td><td>{{ago(player.occurredAt)}}</td><td><button class="button tiny secondary" (click)="inspectPlayer(player)">Explorar →</button></td></tr>}</tbody></table></div>}@else{<div class="empty"><span class="empty-icon">♧</span><strong>Nenhum perfil encontrado</strong><p>Habilite player-state no plugin e aguarde jogadores autenticados no AuthMe.</p></div>}</section>}
@case('worlds') {<div class="world-grid">@for(world of worlds(); track world.id){<section class="card world-card"><div class="world-art" [class.nether]="world.payload.environment === 'NETHER'" [class.end]="world.payload.environment === 'THE_END'"><span>▰</span><span>▰</span><span>▰</span><small>{{world.payload.environment}}</small></div><div class="world-body"><div class="card-heading"><h2>{{world.payload.name}}</h2><span class="pill">{{world.payload.difficulty}}</span></div><dl><div><dt>Chunks carregados</dt><dd>{{world.payload.loadedChunks}}</dd></div><div><dt>Entidades</dt><dd>{{world.payload.entities}}</dd></div><div><dt>Jogadores</dt><dd>{{world.payload.players}}</dd></div><div><dt>Clima</dt><dd>{{world.payload.thunder ? 'Tempestade' : world.payload.storm ? 'Chuva' : 'Limpo'}}</dd></div><div><dt>Horário</dt><dd>{{world.payload.time}} ticks</dd></div></dl><button class="button secondary full" (click)="inspectWorld(world)">Consultar detalhes ↗</button><small class="muted">{{ago(world.occurredAt)}}</small></div></section>}@empty{<section class="card empty"><span class="empty-icon">▰</span><h2>Aguardando seus mundos</h2><p>Os mundos aparecerão após a coleta do plugin.</p></section>}</div>}
@case('events') {<section class="card"><div class="card-heading"><div><h2>Linha do tempo do servidor</h2><p>Até 500 registros nesta janela</p></div><div class="inline-fields"><select aria-label="Período de eventos" [ngModel]="hours()" (ngModelChange)="changeHours(+$event)">@for(hour of hoursOptions;track hour){<option [ngValue]="hour">{{hour === 168 ? '7 dias' : hour + ' horas'}}</option>}</select><input [(ngModel)]="search" class="search-input" placeholder="Filtrar atividade" aria-label="Filtrar atividade"></div></div><div class="toolbar"><span class="muted small">{{filteredEvents().length}} registros visíveis</span><div><a class="button tiny secondary" [href]="exportUrl('json')">Exportar JSON ↗</a> <a class="button tiny secondary" [href]="exportUrl('csv')">CSV</a></div></div>@if(filteredEvents().length){<div class="activity-list">@for(event of filteredEvents(); track event.id){<button class="activity-row event-button" (click)="showResult(event)"><span class="event-assets">@if(event.payload?.uuid || isPlayer()){<vos-head [skin]="eventSkin(event)" [name]="event.payload?.name || api.identity()?.displayName || ''"/>}@else{<span class="event-icon">◈</span>}</span><div><strong>{{eventName(event.type)}}</strong><small>{{event.payload.name || event.type}}</small></div><span>{{date(event.occurredAt)}}</span><span>↗</span></button>}</div>}@else{<div class="empty"><span class="empty-icon">◷</span><strong>Nenhuma atividade encontrada</strong><p>Ajuste a busca ou aguarde novos eventos.</p></div>}</section>}
@case('explorer') {<section class="card query-card"><div class="card-heading"><div><h2>Explore os dados do servidor</h2><p>Consultas sob demanda respeitam os limites e a política do plugin.</p></div><span class="pill" [class.ok]="selected().controlConnected">{{selected().controlConnected ? 'Canal conectado' : 'Canal offline'}}</span></div><form (ngSubmit)="$event.preventDefault()"><label>O que você quer consultar?<select [(ngModel)]="queryOperation" name="query" (ngModelChange)="queryArgs = {}; queryChanged()">@for(operation of queryOperations();track operation){<option [value]="operation">{{name(operation)}}</option>}</select></label><div class="form-grid">@for(field of queryFields();track field){<label>{{fieldName(field)}}<input [type]="isNumber(field, queryOperation) ? 'number' : 'text'" [ngModel]="queryArgs[field] ?? ''" (ngModelChange)="queryArgs[field] = $event; queryChanged()" [name]="field" [attr.list]="field === 'worldId' ? 'world-ids' : field === 'playerId' ? 'player-ids' : null" [placeholder]="field.endsWith('Id') ? 'UUID' : ''"></label>}</div><p class="helper-box">{{queryHint()}}</p></form></section>@if(result()){<section class="card result-card"><div class="card-heading"><h2>Resultado da consulta</h2><span class="pill" [class.ok]="result().state === 'SUCCEEDED'">{{stateName(result().state)}}</span></div><div class="visual-preview">@for(id of visualIds(result().payload);track id){<vos-item [value]="id" [label]="true" (inspect)="inspectItem($event)"/>}</div>@if(queryOperation.startsWith('player.') && result().payload?.skin){<vos-skin [skin]="result().payload.skin" [name]="result().payload.name || ''"/>}<pre>{{json(result().payload ?? result())}}</pre></section>}}
@case('controls') {<div class="notice">Somente operações habilitadas localmente no plugin podem executar. Ações de alto risco exigem Owner e confirmação de identidade.</div><div class="controls-grid"><section class="card"><div class="card-heading"><div><h2>Uma ação, com responsabilidade</h2><p>Toda solicitação recebe um identificador e auditoria.</p></div></div>@if(actionBlockReason()){<div class="notice">{{actionBlockReason()}}</div>}<form (ngSubmit)="confirmAction()"><label>Operação<select [(ngModel)]="actionOperation" name="action" (ngModelChange)="actionArgs = {}">@for(operation of actionOperations();track operation){<option [value]="operation" [disabled]="catalog()?.actions?.[operation]?.risk === 'HIGH' && selected().role !== 'OWNER'">{{name(operation)}}{{catalog()?.actions?.[operation]?.risk === 'HIGH' ? ' · Owner' : ''}}</option>}</select></label><div class="form-grid">@for(field of actionFields();track field){<label>{{fieldName(field)}}@if(choices(actionOperation,field).length){<select [(ngModel)]="actionArgs[field]" [name]="field" required><option value="">Selecione</option>@for(choice of choices(actionOperation,field);track choice){<option [value]="choice">{{choice}}</option>}</select>}@else{<input [type]="isNumber(field,actionOperation) ? 'number' : 'text'" [(ngModel)]="actionArgs[field]" [name]="field" [attr.list]="field === 'worldId' ? 'world-ids' : field === 'playerId' ? 'player-ids' : null" required>}</label>}</div><button class="button primary" type="submit" [disabled]="busy() || !selected().controlConnected || !!actionBlockReason()">Revisar e confirmar →</button></form></section><section class="card safety-card"><span class="safety-icon">◈</span><h2>Você está no controle</h2><p>Confira o alvo antes de confirmar. O plugin valida novamente a operação e sua autorização.</p><ul><li>Player nunca executa ações administrativas.</li><li>Inventário, border e console têm confirmação reforçada.</li><li>Uma ação sem resposta fica sem confirmação; não repita automaticamente.</li></ul><a [routerLink]="prefix() + '/audit'" class="text-link">Consultar auditoria →</a></section></div><section class="card"><div class="card-heading"><h2>Histórico de solicitações</h2><span class="muted small">Até 100 operações</span></div>@if(actions().length){<div class="table-scroll"><table><thead><tr><th>Operação</th><th>Estado</th><th>Risco</th><th>Solicitada em</th><th></th></tr></thead><tbody>@for(action of actions();track action.id){<tr><td><strong>{{name(action.operation)}}</strong><small class="block muted">{{short(action.id)}}</small></td><td><span class="pill" [class.ok]="action.state === 'SUCCEEDED'" [class.danger]="action.state === 'FAILED'">{{stateName(action.state)}}</span></td><td>{{action.risk}}</td><td>{{date(action.created_at)}}</td><td><button class="icon-button" (click)="loadAction(action.id)" aria-label="Ver resultado">↗</button></td></tr>}</tbody></table></div>}@else{<div class="empty"><strong>Nenhuma solicitação ainda</strong><p>Consultas e ações aparecerão aqui depois de executadas.</p></div>}</section>}
@case('audit') {<section class="card"><div class="card-heading"><div><h2>Transparência em cada ação</h2><p>Registro de acesso e operação, sem senhas ou argumentos sensíveis.</p></div></div>@if(audit().length){<div class="table-scroll"><table><thead><tr><th>Operação</th><th>Resultado</th><th>Ator</th><th>Data e hora</th></tr></thead><tbody>@for(entry of audit();track entry.id){<tr><td>{{name(entry.operation)}}</td><td><span class="pill">{{stateName(entry.outcome)}}</span></td><td><code>{{short(entry.actor_id)}}</code></td><td>{{date(entry.created_at)}}</td></tr>}</tbody></table></div>}@else{<div class="empty"><strong>Nenhum registro disponível</strong></div>}</section>}
@case('settings') {<div class="settings-grid"><section class="card"><div class="card-heading"><div><h2>Seu servidor</h2><p>Identidade e acesso ao portal</p></div><span class="pill">{{selected().role}}</span></div><form (ngSubmit)="saveSettings()"><label>Nome do servidor<input [(ngModel)]="serverName" name="serverName" maxlength="80" [disabled]="selected().role !== 'OWNER'"></label><label class="checkbox-label"><input type="checkbox" [(ngModel)]="playerLogin" name="playerLogin" [disabled]="selected().role !== 'OWNER'">Permitir login Player com AuthMe</label><dl><div><dt>Servidor</dt><dd><code>{{selected().id}}</code></dd></div><div><dt>Tenant</dt><dd><code>{{selected().tenantId}}</code></dd></div></dl><button class="button primary" type="submit" [disabled]="selected().role !== 'OWNER' || busy()">Salvar alterações</button></form></section>
<section class="card"><div class="card-heading"><div><h2>Conexão do agente</h2><p>Copie para a configuração local do plugin.</p></div></div><label>Heartbeat<input readonly [value]="settings()?.heartbeat || ''"></label><label>Telemetria<input readonly [value]="settings()?.telemetry || ''"></label><label>Controle<input readonly [value]="settings()?.control || ''"></label><label>Chave pública Ed25519<textarea readonly rows="3" [value]="settings()?.publicKey || ''"></textarea></label><p class="small muted">Coleta sensível e permissões de escrita são habilitadas na configuração do plugin. O painel não altera essa política local.</p>@if(selected().role === 'OWNER'){<button class="button secondary" (click)="open('rotate')">Rotacionar credencial do agente</button>}</section>
<section class="card"><div class="card-heading"><div><h2>Política de coleta</h2><p>Capacidades informadas pelo agente</p></div></div><div class="capability-list">@for(flag of privacyFlags;track flag.key){<div><span>{{flag.label}}</span><span class="pill" [class.ok]="selected().capabilities?.privacy?.[flag.key]">{{selected().capabilities?.privacy?.[flag.key] ? 'Habilitado' : 'Desabilitado / não informado'}}</span></div>}</div></section>
@if(selected().role === 'OWNER'){<section class="card"><div class="card-heading"><div><h2>Administradores</h2><p>Acesso restrito a este servidor</p></div><button class="button tiny secondary" (click)="open('member')">+ Adicionar</button></div>@for(member of members();track member.id){<div class="member-row"><div><strong>{{member.email}}</strong><small>Admin</small></div><button class="icon-button" (click)="removeMember(member)" aria-label="Remover administrador">×</button></div>}@empty{<p class="muted">Nenhum administrador adicional.</p>}<button class="button tiny secondary" (click)="open('server')">+ Vincular outro servidor</button></section>}
<section class="card full-span"><div class="card-heading"><div><h2>Solicitações de privacidade</h2><p>Pedidos dos jogadores para revisão administrativa.</p></div></div>@for(request of privacyRequests();track request.id){<div class="member-row"><div><strong>{{request.kind === 'DELETE' ? 'Solicitação de exclusão' : 'Solicitação de exportação'}}</strong><small>{{short(request.player_id)}} · {{date(request.created_at)}}</small></div><span class="pill">{{request.state}}</span></div>}@empty{<p class="muted">Nenhuma solicitação pendente.</p>}</section></div>}
@case('journey') {<section class="card"><div class="card-heading"><div><h2>Seu caminho no Survival</h2><p>Até 200 eventos próprios dos últimos sete dias.</p></div></div>@for(event of recentSelf(200);track event.id){<button class="activity-row event-button" (click)="showResult(event)"><span class="event-assets">@if(event.payload?.uuid || isPlayer()){<vos-head [skin]="eventSkin(event)" [name]="event.payload?.name || api.identity()?.displayName || ''"/>}@else{<span class="event-icon">◈</span>}</span><div><strong>{{eventName(event.type)}}</strong><small>{{date(event.occurredAt)}}</small></div><span>↗</span></button>}@empty{<div class="empty"><strong>Ainda não há eventos vinculados a você</strong><p>A coleta precisa estar habilitada pelo administrador.</p></div>}</section>}
@case('inventory') {<section class="card player-appearance"><vos-skin [skin]="self()?.skin" [name]="api.identity()?.displayName || ''"/><div><h2>{{api.identity()?.displayName}}</h2><p class="muted">Aparência e inventário do seu personagem no servidor.</p></div></section><section class="card"><div class="card-heading"><div><h2>Seu inventário, à vista</h2><p>Consulta privada do inventário e Ender Chest do seu personagem.</p></div></div><p class="helper-box">Requer coleta de inventários habilitada e seu personagem autenticado no jogo.</p>@if(result()?.payload?.inventory){<h3>Inventário</h3><div class="inventory-grid">@for(slot of result().payload.inventory;track slot.slot){<div class="inventory-slot" [title]="slot.item.type + ' · slot ' + slot.slot"><vos-item [value]="slot.item.type" [amount]="slot.item.amount" (inspect)="inspectItem($event)"/><small>{{slot.slot}}</small></div>}</div><h3>Ender Chest</h3><div class="inventory-grid">@for(slot of result().payload.enderChest;track slot.slot){<div class="inventory-slot" [title]="slot.item.type"><vos-item [value]="slot.item.type" [amount]="slot.item.amount" (inspect)="inspectItem($event)"/><small>{{slot.slot}}</small></div>}@empty{<p class="muted">Nenhum item registrado nesta consulta.</p>}</div>}@else{<div class="empty"><span class="empty-icon">▦</span><strong>{{result() ? stateName(result().state) : 'Carregando seu inventário…'}}</strong><p>O inventário carrega e acompanha o jogo automaticamente enquanto esta tela está aberta.</p></div>}</section>}
@case('statistics') {<section class="card"><div class="card-heading"><div><h2>Números da sua jornada</h2><p>Estatísticas nativas do Minecraft, consultadas pelo seu UUID.</p></div></div>@if(result()?.payload?.items){<div class="stat-list">@for(item of result().payload.items;track $index){<div><span>{{itemName(item.statistic)}}</span><strong>{{item.value | number}}</strong></div>}</div>@if(result().payload.nextOffset >= 0){<button class="button secondary" (click)="ownQuery('player.statistics', result().payload.nextOffset)">Próxima página →</button>}}@else{<div class="empty"><span class="empty-icon">⌁</span><strong>Carregando suas estatísticas…</strong><p>Seu personagem precisa estar autenticado no jogo para consultar.</p></div>}</section>}
@case('advancements') {<section class="card"><div class="card-heading"><div><h2>Pequenas vitórias, grandes histórias</h2><p>Conquistas e critérios observados pelo Minecraft.</p></div></div>@for(item of result()?.payload?.items || [];track item.key){<div class="member-row">@if(item.icon){<vos-item [value]="item.icon" (inspect)="inspectItem($event)"/>}<div><strong>{{itemName(item.key)}}</strong><small>{{item.remaining?.length || 0}} critérios restantes</small></div><span class="pill" [class.ok]="item.complete">{{item.complete ? 'Concluída' : 'Em andamento'}}</span></div>}@empty{<div class="empty"><span class="empty-icon">✧</span><strong>Carregando suas conquistas…</strong><p>Consulte enquanto estiver autenticado no jogo.</p></div>}@if(result()?.payload?.nextOffset >= 0){<button class="button secondary" (click)="ownQuery('player.advancements', result().payload.nextOffset)">Próxima página →</button>}</section>}
@case('privacy') {<section class="card privacy-card"><span class="safety-icon">◈</span><h2>Seus dados, com contexto</h2><p>Você acessa somente seu próprio perfil. Os administradores podem consultar os dados coletados de seus servidores conforme a política informada pela comunidade.</p><p>Você pode solicitar uma cópia ou a exclusão dos seus dados. O administrador receberá o pedido para revisão e atendimento.</p><div class="inline-fields"><button class="button secondary" (click)="privacyRequest('EXPORT')">Solicitar exportação</button><button class="button danger-button" (click)="privacyRequest('DELETE')">Solicitar exclusão</button></div></section>}
}
<footer class="page-footer"><span>VanillaOnlineStats · dados observados, sem estimativas inventadas</span><span>{{lastRefresh() ? 'Atualizado ' + ago(lastRefresh()) : 'Aguardando atualização'}}</span></footer>
}
</main></div></div>
<datalist id="player-ids">@for(player of players();track player.id){<option [value]="player.id">{{player.payload.name}}</option>}</datalist><datalist id="world-ids">@for(world of worlds();track world.id){<option [value]="world.id">{{world.payload.name}}</option>}</datalist>
<dialog #dialog (cancel)="close()"><div class="dialog-heading"><h2>{{dialogTitle()}}</h2><button class="icon-button" (click)="close()" aria-label="Fechar">×</button></div>
@switch(dialogType()) {
@case('item'){<div class="item-detail"><img [src]="itemImage()" [alt]="itemDetails()?.name"><h3>{{itemDetails()?.name}}</h3><code>{{itemDetails()?.id}}</code><p class="muted">{{itemDetails()?.mod}}</p>@if(itemColor()){<div class="item-color"><i [style.background]="itemColor()"></i>{{itemColor()}}</div>}@if(itemDetails()?.type === 'block'){<div class="segmented">@for(angle of ['iso','front','side','top','low'];track angle){<button (click)="itemAngle.set(angle)" [class.selected]="itemAngle()===angle">{{angle}}</button>}</div>}@if(itemDetails()?.unavailable){<p>Metadados indisponíveis. O item original permanece identificado acima.</p>}@if(itemDetails()?.properties){<pre class="result-json">{{json(itemDetails()?.properties)}}</pre>}<a class="text-link" href="https://blocksitems.com/pt-BR" target="_blank" rel="noopener">Dados e imagens: BlocksItems ↗</a></div>}@case('result'){<div class="visual-preview">@for(id of visualIds(dialogResult()?.payload || dialogResult());track id){<vos-item [value]="id" [label]="true" (inspect)="inspectItem($event)"/>}</div><p class="error-banner" [hidden]="!dialogResult()?.state || dialogResult()?.state==='SUCCEEDED'">{{controlReason(dialogResult())}}</p><pre class="result-json">{{json(dialogResult())}}</pre>}
@case('account'){<p class="muted">{{api.identity()?.displayName}}</p><dl><div><dt>Área</dt><dd>{{isPlayer() ? 'Player' : 'Admin'}}</dd></div><div><dt>Sessão válida até</dt><dd>{{date(api.identity()?.expiresAt)}}</dd></div></dl>@if(!isPlayer()){<form (ngSubmit)="changePassword()"><h3>Alterar senha</h3><label>Senha atual<input type="password" name="current" [(ngModel)]="currentPassword" autocomplete="current-password" required></label><label>Nova senha<input type="password" name="new" [(ngModel)]="newPassword" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="button primary full" [disabled]="busy()">Salvar nova senha</button></form><br>}<button class="button secondary full" (click)="logout()">Sair do portal</button>}
@case('action'){<p>Confirme a operação <strong>{{name(actionOperation)}}</strong>.</p><dl>@for(field of actionFields();track field){<div><dt>{{fieldName(field)}}</dt><dd>{{actionArgs[field]}}</dd></div>}</dl>@if(catalog()?.actions?.[actionOperation]?.risk === 'HIGH'){<div class="notice">Operação de alto risco. Confira o alvo e confirme sua identidade.</div><label>Sua senha de Owner<input type="password" [(ngModel)]="reauthPassword" autocomplete="current-password"></label>}<label class="checkbox-label"><input type="checkbox" [(ngModel)]="confirmed">Conferi o alvo e quero executar esta operação.</label><div class="dialog-actions"><button class="button secondary" (click)="close()">Cancelar</button><button class="button primary" (click)="executeAction()" [disabled]="!confirmed || busy()">{{busy() ? 'Executando…' : 'Confirmar operação'}}</button></div>}
@case('server'){<form (ngSubmit)="addServer()"><p class="muted">Use o serverId mostrado por <code>vos status</code> no console do Paper.</p><label>Nome<input [(ngModel)]="newServerName" name="name" required maxlength="80" placeholder="Meu Survival"></label><label>Server ID<input [(ngModel)]="newServerId" name="id" required placeholder="UUID do plugin"></label><button class="button primary full" [disabled]="busy()">Vincular servidor</button></form>}
@case('token'){<div class="notice">Copie agora. Esta credencial não será exibida novamente. Configure como VOS_AGENT_TOKEN no ambiente do Paper.</div><textarea readonly rows="3" [value]="oneTimeToken" aria-label="Credencial de agente gerada"></textarea><button class="button primary" (click)="copyToken()">Copiar credencial</button>}
@case('rotate'){<p>A credencial atual será invalidada e o canal do plugin será encerrado. Você precisará configurar o novo token e reiniciar o Paper.</p><label>Sua senha de Owner<input type="password" [(ngModel)]="reauthPassword" autocomplete="current-password"></label><button class="button danger-button full" [disabled]="busy()" (click)="rotateToken()">Confirmar rotação</button>}
@case('member'){<form (ngSubmit)="addMember()"><label>E-mail do administrador<input type="email" [(ngModel)]="memberEmail" name="email" required></label><label>Senha inicial (apenas conta nova)<input type="password" [(ngModel)]="memberPassword" name="password" minlength="12" autocomplete="new-password"></label><p class="small muted">Se a conta já existir, a senha dela será preservada.</p><button class="button primary full" [disabled]="busy()">Conceder acesso Admin</button></form>}
}@if(dialogError()){<div class="error-banner" role="alert">{{dialogError()}}</div>}</dialog>
` })
export class Panel implements OnDestroy {
  api = inject(Api); theme = inject(Theme); router = inject(Router); route = inject(ActivatedRoute);
  @ViewChild('dialog') dialog!: ElementRef<HTMLDialogElement>;
  section = signal('overview'); servers = signal<any[]>([]); serverId = signal(''); selected = computed(() => this.servers().find(s => s.id === this.serverId()));
  overview = signal<any>(null); self = signal<any>(null); players = signal<any[]>([]); worlds = signal<any[]>([]); events = signal<any[]>([]); metrics = signal<any[]>([]); actions = signal<any[]>([]); audit = signal<any[]>([]); members = signal<any[]>([]); privacyRequests = signal<any[]>([]); catalog = signal<any>(null); settings = signal<any>(null); result = signal<any>(null);
  loading = signal(false); busy = signal(false); error = signal(''); notice = signal(''); navOpen = signal(false); lastRefresh = signal(''); hours = signal(24); metric = signal('tps'); dialogType = signal(''); dialogError = signal(''); dialogResult = signal<any>(null);
  isPlayer = computed(() => this.api.identity()?.kind === 'PLAYER'); prefix = computed(() => this.isPlayer() ? '/player' : '/admin'); initials = computed(() => (this.api.identity()?.displayName ?? 'V').slice(0,2).toUpperCase());
  navigation = computed(() => this.isPlayer() ? [{ id:'overview',icon:'▦' },{id:'journey',icon:'◷'},{id:'inventory',icon:'▣'},{id:'statistics',icon:'⌁'},{id:'advancements',icon:'✧'},{id:'privacy',icon:'◈'}] : [{id:'overview',icon:'▦'},{id:'players',icon:'♧'},{id:'worlds',icon:'▰'},{id:'events',icon:'◷'},{id:'explorer',icon:'⌕'},{id:'controls',icon:'⇄'},{id:'audit',icon:'✓'},{id:'settings',icon:'⚙'}]);
  snapshots = computed(() => Object.fromEntries((this.overview()?.snapshots ?? []).map((e: any) => [e.id, e.payload])));
  perf = computed(() => this.snapshots()['server.performance.snapshot'] ?? {}); heartbeat = computed(() => this.snapshots()['server.heartbeat'] ?? {}); metadata = computed(() => this.snapshots()['server.metadata.snapshot'] ?? {});
  activeAlerts = computed(() => (this.overview()?.alerts ?? []).filter((a: any) => a.active));
  themes: { id:'auto' | 'light' | 'dark'; icon:string; label:string }[] = [{id:'light',icon:'☀',label:'Tema claro'},{id:'dark',icon:'☾',label:'Tema escuro'},{id:'auto',icon:'◐',label:'Seguir tema do sistema'}];
  privacyFlags = [{key:'players',label:'Estado dos jogadores'},{key:'inventories',label:'Inventários e Ender Chest'},{key:'positions',label:'Posições precisas'},{key:'addresses',label:'Endereços de conexão'},{key:'seeds',label:'Seed dos mundos'}];
  hoursOptions = [1,6,24,168]; search = ''; queryOperation = 'server.performance'; queryArgs: Record<string,any> = {}; actionOperation = 'world.time'; actionArgs: Record<string,any> = {}; confirmed = false; reauthPassword = ''; oneTimeToken = ''; newServerId = ''; newServerName = ''; serverName = ''; playerLogin = false; memberEmail = ''; memberPassword = '';
  itemCatalog = inject(ItemCatalog); visualIds = visualIds; itemDetails = signal<any>(null); itemAngle = signal('iso');
  currentPassword = ''; newPassword = '';
  streamState=signal('Conectando'); queryError=signal(''); pageOffset=0; private reader=new LiveReader(); private autoKey=''; private destroyed=false;
  private visibility=()=>{if(!document.hidden){this.reader.reset();void this.refresh(true);this.automaticQuery();}};
  private stream?: EventSource; private pendingRefresh?: ReturnType<typeof setTimeout>; private dirty = false;
  private timer: ReturnType<typeof setInterval>; private subscription; private initialized = false; private initializing=false; private initializeAfter=0; private initializeFailures=0; private loadEpoch = 0;
  constructor() {
    this.subscription = this.route.paramMap.subscribe(params => { this.section.set(params.get('section') ?? 'overview'); this.search = ''; this.pageOffset=0; this.reader.reset();this.autoKey='';this.queryError.set('');this.result.set(null); if (this.initialized) { this.loadEpoch++; this.loading.set(false); void this.refresh(); } });
    void this.initialize(); document.addEventListener('visibilitychange',this.visibility); this.timer=setInterval(()=>{if(document.hidden)return;if(!this.initialized||!this.serverId()){void this.initialize();return;}if(!this.loading() && Date.now()-Date.parse(this.lastRefresh()||'1970-01-01')>=2000)void this.refresh(true);this.automaticQuery();},1000);
  }
  async initialize() { if(this.initializing||this.destroyed||Date.now()<this.initializeAfter)return;this.initializing=true;try { this.api.info.set(await this.api.request('public/info')); const servers = await this.api.request<any[]>('servers'); this.servers.set(servers); const previous = sessionStorage.getItem('vos_server'); this.serverId.set(servers.some(s => s.id === previous) ? previous! : servers[0]?.id ?? ''); this.initialized = true;this.initializeFailures=0; this.connectStream(); await this.refresh(); } catch(error: any) { this.initializeAfter=Date.now()+Math.min(30000,1000*2**++this.initializeFailures);this.error.set(error.message); if (!this.api.identity()) void this.router.navigateByUrl('/login'); } finally{this.initializing=false;} }
  ngOnDestroy() { this.destroyed=true;this.reader.reset();document.removeEventListener('visibilitychange',this.visibility);clearInterval(this.timer); this.stream?.close(); clearTimeout(this.pendingRefresh); this.subscription.unsubscribe(); this.oneTimeToken = ''; this.reauthPassword = ''; }
  name(value: string) { return labels[value] ?? value; }
  headline() { return this.section() === 'overview' ? this.isPlayer() ? 'Toda jornada merece ser lembrada.' : 'Seu mundo, em perspectiva.' : this.name(this.section()); }
  subtitle() { return this.section() === 'overview' ? this.isPlayer() ? 'Acompanhe sua história no Survival, com seus dados em um só lugar.' : 'Acompanhe o desempenho, os jogadores e os acontecimentos do seu servidor.' : this.isPlayer() ? 'Informações privadas vinculadas à sua identidade no jogo.' : 'Informações e operações do servidor selecionado.'; }
  async selectServer(value: string) { this.reader.reset();this.autoKey='';this.pageOffset=0;this.queryError.set('');this.loadEpoch++; this.loading.set(false); this.serverId.set(value); sessionStorage.setItem('vos_server',value); this.overview.set(null); this.self.set(null); this.result.set(null); this.players.set([]); this.worlds.set([]); this.events.set([]); this.metrics.set([]); this.actions.set([]); this.audit.set([]); this.catalog.set(null); this.settings.set(null); this.connectStream(); await this.refresh(); }
  async refresh(quiet = false) {
    if (!this.serverId() || this.loading()) return; const epoch = ++this.loadEpoch; this.loading.set(true); if(!quiet) this.error.set('');
    try {
      const id = this.serverId(), base = 'servers/' + id, section = this.section();
      if (this.isPlayer()) { const self = await this.api.request('me/servers/' + id); if(epoch !== this.loadEpoch) return; this.self.set(self); if(!this.selected()?.controlConnected&&self.server.controlConnected)this.reader.reset();this.servers.update(values=>values.map(v=>v.id===id?self.server:v)); }
      else {
        const overview = await this.api.request(base + '/overview'); if(epoch !== this.loadEpoch) return; this.overview.set(overview);if(!this.selected()?.controlConnected&&overview.server.controlConnected)this.reader.reset();this.servers.update(values => values.map(s => s.id === id ? overview.server : s));
        const jobs: Promise<any>[] = [];
        if(section === 'overview') { jobs.push(this.api.request<any[]>(base + '/metrics?hours=' + this.hours()).then(v => { if(epoch === this.loadEpoch) this.metrics.set(v); })); jobs.push(this.api.request<any[]>(base + '/events?hours=1').then(v => { if(epoch === this.loadEpoch) this.events.set(v); })); }
        if(['overview','events','players','controls','explorer'].includes(section)) jobs.push(this.api.request<any[]>(base + '/players').then(v => { if(epoch === this.loadEpoch) this.players.set(v); }));
        if(['worlds','controls','explorer'].includes(section)) jobs.push(this.api.request<any[]>(base + '/worlds').then(v => { if(epoch === this.loadEpoch) this.worlds.set(v); }));
        if(section === 'events') jobs.push(this.api.request<any[]>(base + '/events?hours=' + this.hours()).then(v => { if(epoch === this.loadEpoch) this.events.set(v); }));
        if(['controls','explorer'].includes(section)) jobs.push(this.api.request(base + '/catalog').then(v => { if(epoch === this.loadEpoch) this.catalog.set(v); }));
        if(section === 'controls') jobs.push(this.api.request<any[]>(base + '/actions').then(v => { if(epoch === this.loadEpoch) this.actions.set(v); }));
        if(section === 'audit') jobs.push(this.api.request<any[]>(base + '/audit').then(v => { if(epoch === this.loadEpoch) this.audit.set(v); }));
        if(section === 'settings') { jobs.push(this.api.request(base + '/settings').then((v: any) => { if(epoch !== this.loadEpoch) return; this.settings.set(v); if(!quiet){this.serverName = v.name; this.playerLogin = v.playerLogin;} })); jobs.push(this.api.request<any[]>(base + '/privacy-requests').then(v => { if(epoch === this.loadEpoch) this.privacyRequests.set(v); })); if(overview.server.role === 'OWNER') jobs.push(this.api.request<any[]>(base + '/members').then(v => { if(epoch === this.loadEpoch) this.members.set(v); })); }
        await Promise.all(jobs);
      }
      if(epoch === this.loadEpoch) { this.lastRefresh.set(new Date().toISOString()); this.error.set('');this.automaticQuery(); }
    } catch(error: any) { if(epoch === this.loadEpoch) this.error.set(error.message); if(!this.api.identity()) void this.router.navigateByUrl('/login'); } finally { if(epoch === this.loadEpoch) this.loading.set(false); }
  }
  private connectStream() {
    this.stream?.close(); clearTimeout(this.pendingRefresh); this.dirty=false;
    if(!this.serverId())return;
    this.streamState.set('Conectando');this.stream=new EventSource('/api/v1/servers/'+this.serverId()+'/stream');
    this.stream.addEventListener('open',()=>this.streamState.set('Ao vivo'));this.stream.addEventListener('error',()=>this.streamState.set('Reconectando'));
    this.stream.addEventListener('update',()=>{this.dirty=true;this.scheduleUpdate();});
    this.stream.addEventListener('expired',()=>{this.stream?.close();void this.api.me().then(()=>this.router.navigateByUrl('/login'));});
  }
  private scheduleUpdate() {
    if(this.pendingRefresh)return;
    this.pendingRefresh=setTimeout(()=>{this.pendingRefresh=undefined;if(!this.dirty)return;if(document.hidden)return;if(this.loading()){this.scheduleUpdate();return;}this.dirty=false;void this.refresh(true);},350);
  }
  queryChanged() { this.reader.reset();this.autoKey='';this.result.set(null);this.queryError.set(''); }
  queryHint() { return this.queryFields().some(field=>!['offset','statistic','material','entityType'].includes(field)&&(this.queryArgs[field]==null||this.queryArgs[field]===''||field.endsWith('Id')&&!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(this.queryArgs[field])))) ? 'Preencha o alvo para acompanhar a consulta automaticamente.' : 'Consulta acompanhada automaticamente enquanto esta tela está aberta.'; }
  private automaticQuery() {
    if(this.destroyed || document.hidden || !this.initialized || !this.serverId())return;
    const own:Record<string,string>={inventory:'player.inventory',statistics:'player.statistics',advancements:'player.advancements'};
    const operation=this.isPlayer()?own[this.section()]:this.section()==='explorer'?this.queryOperation:null;
    if(!operation){void this.reader.poll(null,async()=>null,()=>{},()=>{});return;}
    if(!this.isPlayer()&&this.queryHint().startsWith('Preencha')){this.reader.reset();this.result.set(null);this.queryError.set('');return;}
    const args=this.isPlayer()?(this.pageOffset?{offset:this.pageOffset}:{}):this.parameters(this.queryArgs,operation);
    const base=(this.isPlayer()?'me/':'')+'servers/'+this.serverId()+'/live';
    const path=base+'?operation='+encodeURIComponent(operation)+'&arguments='+encodeURIComponent(JSON.stringify(args));
    if(this.autoKey!==path){this.autoKey=path;this.result.set(null);this.queryError.set('');}
    void this.reader.poll(path,()=>this.api.request(path),value=>{if(this.destroyed)return;this.result.set(value);this.queryError.set(value.state==='SUCCEEDED'?'':this.controlReason(value));},error=>{if(!this.destroyed)this.queryError.set(error.message);});
  }
  async changeHours(value: number) { this.hours.set(value); await this.refresh(); }
  heapPercent() { return this.perf().heapMax > 0 ? Math.min(100,100*this.perf().heapUsed/this.perf().heapMax) : 0; }
  number(value: any, digits = 0) { return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value.toLocaleString('pt-BR',{ minimumFractionDigits:digits,maximumFractionDigits:digits }) : '—'; }
  date(value: any) { return value ? new Date(value).toLocaleString('pt-BR') : 'Não informado'; }
  ago(value: any) { if(!value) return 'ainda não recebido'; const seconds = Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000)); return seconds < 60 ? `há ${seconds}s` : seconds < 3600 ? `há ${Math.floor(seconds/60)} min` : seconds < 86400 ? `há ${Math.floor(seconds/3600)}h` : `há ${Math.floor(seconds/86400)} dias`; }
  short(value: string) { return value ? value.slice(0,8) + '…' + value.slice(-4) : '—'; }
  json(value: any) { return JSON.stringify(value,null,2); }
  itemName(value: string) { return String(value).replace(/^minecraft:/,'').replaceAll('_',' '); }
  eventName(value: string) { const names: Record<string,string> = {'auth.session.started':'Sessão autenticada iniciada','auth.session.ended':'Sessão encerrada','server.heartbeat':'Servidor enviou um sinal','server.performance.snapshot':'Desempenho atualizado','worlds.snapshot':'Mundos sincronizados','players.snapshot':'Jogadores sincronizados','server.metadata.snapshot':'Informações do servidor atualizadas','events.counters':'Contadores de eventos atualizados'}; return names[value] ?? value.split('.').at(-1)?.replace(/Event$/,'').replace(/([a-z])([A-Z])/g,'$1 $2') ?? value; }
  stateName(value: string) { return ({SUCCEEDED:'Concluída',FAILED:'Não executada / falhou',REJECTED:'Recusada',EXPIRED:'Expirada',UNKNOWN:'Sem confirmação',PENDING:'Pendente',RUNNING:'Em execução'} as Record<string,string>)[value] ?? value; }
  alertName(rule: string) { return ({'low-tps':'TPS abaixo de 18','high-mspt':'Tick acima de 50 ms','high-heap':'Heap acima de 90%'} as Record<string,string>)[rule] ?? rule; }
  recentEvents() { return this.events().filter(e => !['server.heartbeat','server.performance.snapshot','players.snapshot','worlds.snapshot','events.counters','server.metadata.snapshot','players.live.snapshot'].includes(e.type)).slice().reverse().slice(0,6); }
  eventSkin(event:any) { return this.isPlayer()?this.self()?.skin:this.players().find(p=>p.id===event.payload?.uuid)?.payload.skin; }
  recentSelf(max = 8) { return (this.self()?.events ?? []).slice().reverse().slice(0,max); }
  filteredPlayers() { const search = this.search.toLowerCase(); return this.players().filter(p => (p.payload.name + p.id).toLowerCase().includes(search)); }
  filteredEvents() { const search = this.search.toLowerCase(); return this.events().slice().reverse().filter(e => (e.type + ' ' + (e.payload.name ?? '')).toLowerCase().includes(search)); }
  queryOperations(): string[] { return this.catalog()?.queries ?? []; } actionOperations(): string[] { return Object.keys(this.catalog()?.actions ?? {}); }
  queryFields() { return queryFields[this.queryOperation] ?? []; } actionFields(): string[] { return this.catalog()?.actions?.[this.actionOperation]?.fields ?? []; }
  fieldName(field: string) { return fieldLabels[field] ?? field; }
  isNumber(field: string, operation: string) { return ['x','y','z','size','offset'].includes(field) || field === 'value' && ['world.time','player.health','player.food','player.level'].includes(operation); }
  choices(operation: string, field: string) { if(field === 'mode') return ['SURVIVAL','CREATIVE','ADVENTURE','SPECTATOR']; if(field === 'value' && operation === 'world.weather') return ['clear','rain','thunder']; if(field === 'value' && operation === 'world.difficulty') return ['PEACEFUL','EASY','NORMAL','HARD']; return []; }
  private parameters(values: Record<string,any>, operation: string) { return Object.fromEntries(Object.entries(values).filter(([,v]) => v !== '' && v != null).map(([key,value]) => [key,this.isNumber(key,operation) ? Number(value) : value])); }
  async runQuery() { this.reader.reset();this.autoKey='';this.automaticQuery(); }
  async inspectPlayer(player: any) { this.queryOperation = 'player.snapshot'; this.queryArgs = {playerId:player.id}; await this.router.navigateByUrl(this.prefix()+'/explorer'); await this.runQuery(); }
  async inspectWorld(world: any) { this.queryOperation = 'world.snapshot'; this.queryArgs = {worldId:world.id}; await this.router.navigateByUrl(this.prefix()+'/explorer'); await this.runQuery(); }
  confirmAction() { this.confirmed = false; this.reauthPassword = ''; this.open('action'); }
  async executeAction() { await this.perform(async () => { if(this.catalog()?.actions?.[this.actionOperation]?.risk === 'HIGH') await this.api.post('auth/reauth',{password:this.reauthPassword}); const result = await this.api.post('servers/'+this.serverId()+'/actions',{operation:this.actionOperation,arguments:this.parameters(this.actionArgs,this.actionOperation),confirmed:true}); this.reauthPassword = ''; this.close(); this.showResult(result); await this.refresh(); },true); }
  async ownQuery(_operation: string, offset = 0) { this.pageOffset=offset;this.reader.reset();this.autoKey='';this.automaticQuery(); }
  async ack(rule: string) { await this.perform(async () => { await this.api.post('servers/'+this.serverId()+'/alerts/'+rule+'/ack'); await this.refresh(); }); }
  async saveSettings() { await this.perform(async () => { await this.api.request('servers/'+this.serverId()+'/settings',{method:'PATCH',body:JSON.stringify({name:this.serverName,playerLogin:this.playerLogin})}); this.notice.set('Configuração do portal salva.'); await this.refresh(); }); }
  async addServer() { await this.perform(async () => { const result = await this.api.post('servers',{serverId:this.newServerId.trim(),name:this.newServerName}); this.oneTimeToken = result.agentToken; this.dialogType.set('token'); this.servers.set(await this.api.request('servers')); this.serverId.set(result.serverId);this.connectStream(); this.newServerName = ''; this.newServerId = ''; await this.refresh(); },true); }
  async rotateToken() { await this.perform(async () => { await this.api.post('auth/reauth',{password:this.reauthPassword}); const result = await this.api.post('servers/'+this.serverId()+'/rotate-agent'); this.reauthPassword = ''; this.oneTimeToken = result.agentToken; this.dialogType.set('token'); },true); }
  async copyToken() { try { await navigator.clipboard.writeText(this.oneTimeToken); this.dialogError.set('Credencial copiada. Guarde-a fora do repositório.'); } catch { this.dialogError.set('Copie a credencial manualmente do campo acima.'); } }
  async addMember() { await this.perform(async () => { await this.api.post('servers/'+this.serverId()+'/members',{email:this.memberEmail,password:this.memberPassword}); this.memberPassword = ''; this.memberEmail = ''; this.close(); await this.refresh(); },true); }
  async removeMember(member: any) { if(!window.confirm('Remover o acesso de '+member.email+' a este servidor?')) return; await this.perform(async () => { await this.api.request('servers/'+this.serverId()+'/members/'+member.id,{method:'DELETE'}); await this.refresh(); }); }
  async privacyRequest(kind: string) { if(kind === 'DELETE' && !window.confirm('Enviar ao administrador uma solicitação de exclusão dos seus dados?')) return; await this.perform(async () => { await this.api.post('me/servers/'+this.serverId()+'/privacy-requests',{kind}); this.notice.set('Solicitação enviada para revisão do administrador.'); }); }
  actionBlockReason() { const policy=this.catalog()?.capabilities?.controls;if(!policy)return 'Atualize o plugin para informar as permissões de controle.';if(!policy.writesEnabled)return 'Escritas desativadas no plugin. Configure control.writes-enabled: true e allowed-operations no config.yml e reinicie o Paper.';if(!policy.allowedOperations?.includes(this.actionOperation))return 'Esta operação não está em control.allowed-operations no plugin.';if(this.actionOperation==='server.console'&&!policy.consoleEnabled)return 'Console desativado no plugin.';return ''; }
  controlReason(result:any) { return ({WRITES_DISABLED:'Escritas desativadas: habilite control.writes-enabled no plugin.',OPERATION_NOT_ALLOWED:'Operação ausente da allowlist control.allowed-operations.',ROLE_NOT_ALLOWED:'Sua conta não pode executar esta operação.',OWNER_REQUIRED:'Operação exige Owner e confirmação.',CONSOLE_DISABLED:'Console remoto desativado no plugin.',PLAYER_OFFLINE:'O personagem está offline; a consulta ao vivo exige jogador conectado.',PLAYER_NOT_AUTHENTICATED:'O personagem precisa estar autenticado no AuthMe.',PLAYER_COLLECTION_DISABLED:'Habilite privacy.player-state no plugin e reinicie o Paper.',INVENTORY_COLLECTION_DISABLED:'Habilite privacy.inventories no plugin e reinicie o Paper.',INVALID_ARGUMENTS:'O plugin recusou os argumentos. Confira os valores e o alvo.',IllegalArgumentException:'O plugin recusou a operação. Confira escritas, allowlist, argumentos e autenticação no jogo.'} as Record<string,string>)[result?.payload?.reasonCode] || 'A operação não foi confirmada pelo plugin: '+this.stateName(result?.state); }
  async inspectItem(id:string) { if(!registryId(id))return;this.itemAngle.set('iso');this.itemDetails.set({id,name:id});this.open('item');const detail=await this.itemCatalog.get(id);if(this.dialogType()==='item'&&this.itemDetails()?.id===id)this.itemDetails.set(detail??{id,name:id,unavailable:true}); }
  itemColor() { const color=this.itemDetails()?.colors?.map_color;return /^#[a-f0-9]{6}$/i.test(color??'')?color:null; }
  itemImage() { const item=this.itemDetails();return 'https://blocksitems.com/api/2026.1.2/'+(item?.type==='block'?'blocks/'+encodeURIComponent(item.id)+'/render.png?angle='+this.itemAngle()+'&size=256':'icon/'+encodeURIComponent(item?.id??'')+'.png?size=256'); }
  async loadAction(id: string) { await this.perform(async () => this.showResult(await this.api.request('servers/'+this.serverId()+'/actions/'+id))); }
  exportUrl(format: string) { return '/api/v1/servers/'+this.serverId()+'/export?format='+format+'&hours='+this.hours(); }
  showResult(value: any) { this.dialogResult.set(value); this.open('result'); }
  open(kind: string) { this.dialogError.set(''); this.dialogType.set(kind); this.dialog.nativeElement.showModal(); }
  close() { this.dialog.nativeElement.close(); this.dialogType.set(''); this.dialogError.set(''); this.reauthPassword = ''; this.memberPassword = ''; this.oneTimeToken = ''; this.currentPassword = ''; this.newPassword = ''; }
  dialogTitle() { return ({result:'Detalhes',account:'Sua conta',action:'Revisar operação',server:'Vincular servidor',token:'Credencial do agente',rotate:'Rotacionar credencial',member:'Adicionar administrador',item:'Bloco ou item'} as Record<string,string>)[this.dialogType()] ?? ''; }
  async changePassword() { await this.perform(async () => { await this.api.post('auth/password',{currentPassword:this.currentPassword,newPassword:this.newPassword}); this.close(); this.notice.set('Senha alterada. As outras sessões foram encerradas.'); },true); }
  async logout() { await this.perform(async () => { await this.api.post('auth/logout'); this.api.identity.set(null); this.close(); await this.router.navigateByUrl('/login'); }); }
  private async perform(task: () => Promise<any>, dialog = false) { if(this.busy()) return; this.busy.set(true); this.error.set(''); this.dialogError.set(''); try { await task(); } catch(error:any) { if(dialog) this.dialogError.set(error.message); else this.error.set(error.message); } finally { this.busy.set(false); } }
}
